mapper.select:
/* selectFacilityDataList */ SELECT DISTINCT A.FACILITY_ID AS facilityId ,A.FACILITY_NAME AS facilityName ,B.PART_ID AS partId ,C.STATUS_ID AS statusId ,C.STATUS_NAME AS statusName ,D.LOCATION_DATA AS locationArea FROM FACILITY A, FACILITY_PART B, FACILITY_STATUS C, FACILITY_LOCATION D WHERE 1=1 AND A.FACILITY_ID = B.FACILITY_ID AND A.FACILITY_ID = C.FACILITY_ID AND A.FACILITY_ID = D.FACILITY_ID
AND C.STATUS_NAME_ID = #{stsNameId}
AND D.LOCATION_DATA = #{locationArea}
OFFSET #{firstIndex} ROWS FETCH NEXT #{recordCountPerPage} ROW ONLY

/* selectFacilityCnt */ SELECT COUNT(*) AS cnt FROM ( SELECT DISTINCT A.FACILITY_ID AS facilityId ,A.FACILITY_NAME AS facilityName ,B.PART_ID AS partId ,C.STATUS_ID AS statusId ,C.STATUS_NAME AS statusName ,D.LOCATION_DATA AS locationArea FROM FACILITY A, FACILITY_PART B, FACILITY_STATUS C, FACILITY_LOCATION D WHERE 1=1 AND A.FACILITY_ID = B.FACILITY_ID AND A.FACILITY_ID = C.FACILITY_ID AND A.FACILITY_ID = D.FACILITY_ID
AND C.STATUS_NAME_ID = #{stsNameId}
AND D.LOCATION_DATA IN '(' || #{locationArea} || ')'
) A
